import sys

def main():
    data = sys.stdin.read().split()
    n, T = int(data[0]), int(data[1])
    a = list(map(int, data[2:2 + n]))
    MOD = 10 ** 9 + 7
    dp = [0] * (T + 1)
    dp[0] = 1
    for v in a:
        if v > T:
            continue
        for s in range(T, v - 1, -1):
            if dp[s - v]:
                dp[s] = (dp[s] + dp[s - v]) % MOD
    print(dp[T] % MOD)

main()

