data = sys.stdin.read().split()
n, T = int(data[0]), int(data[1])
a = list(map(int, data[2:2 + n]))
count = 0
for mask in range(1, 1 << n):
    s = 0
    for i in range(n):
        if mask >> i & 1:
            s += a[i]
    if s == T:
        count += 1
print(count % (10 ** 9 + 7))

